def compute(vars):
    old = vars["v1"]
    increase = vars["v2"]
    if old == 0:
        return None
    change_ratio = increase / old
    percentage_increase = change_ratio * 100
    return {
        "value": percentage_increase,
        "trace": {
            "old_berths": old,
            "anticipated_new_berths": increase,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
